CREATE OR REPLACE FUNCTION public.fn_get_latest_weekly_planning_draft_for_week(p_tenant_id uuid, p_classroom_id uuid, p_week_start_date date)  RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, classroom_id uuid, requested_by_user_id uuid, week_start_date date, week_end_date date, focus_areas character varying, indoor_outdoor_preference character varying, materials_notes text, status character varying, created_at timestamp with time zone, updated_at timestamp with time zone)  LANGUAGE sql  STABLE AS $function$     SELECT          id, tenant_id, organization_id, classroom_id, requested_by_user_id,         week_start_date, week_end_date, focus_areas, indoor_outdoor_preference,         materials_notes, status, created_at, updated_at     FROM weekly_planning_draft_requests     WHERE tenant_id = p_tenant_id AND classroom_id = p_classroom_id AND week_start_date = p_week_start_date     ORDER BY created_at DESC     LIMIT 1; $function$ ;
